<?php require 'inc.php'; $u=need();$o=row('SELECT o.*,u.email FROM ordenes o JOIN usuarios u ON u.id=o.usuario_id WHERE o.folio=?','s',$_GET['folio']??'');
if(!$o||($o['usuario_id']!=$u['id']&&$u['rol']!='admin'))go('pedidos.php');$D=rows('SELECT * FROM detalles_orden WHERE orden_id=?','i',$o['id']);head('Pedido '.$o['folio']);$ks=array_keys(ETQ);$cur=array_search($o['estado'],$ks);?>
<div class="fl noprint"><a class="mut" href="pedidos.php">← Mis pedidos</a><button class="btn o" onclick="print()">🖨 Imprimir / guardar comprobante (PDF)</button></div>
